select * from orders



        and shop_id = #{shopId}


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

select * from orders
where user_id = #{userId}

    and status = #{status}


    and (order_time < #{cursorOrderTime} or (order_time = #{cursorOrderTime} and id < #{cursorId}))

order by order_time desc, id desc
limit #{limit}

select sum(amount) from orders


        and shop_id = #{shopId}


        and status = #{status}


        and order_time >= #{begin}


        and order_time <= #{end}

select count(id) from orders


        and shop_id = #{shopId}


        and status = #{status}


        and order_time >= #{begin}


        and order_time <= #{end}

select date(order_time) as date, count(id) as totalOrderCount, sum(case when status = #{validStatus} then 1 else 0 end) as validOrderCount, sum(case when status = #{validStatus} then amount else 0 end) as turnover from orders where order_time >= #{begin} and order_time <= #{end}
and shop_id = #{shopId}
group by date(order_time)

